{"test_code":"from pager.pagination import page_slice, total_pages


def test_last_partial_page_is_reachable() -> None:
    items = list(range(1, 11))
    assert total_pages(10, 3) == 4
    assert page_slice(items, 4, 3) == [10]


def test_all_orders_appear_across_pages() -> None:
    items = list(range(1, 11))
    seen = []
    for page in range(1, total_pages(len(items), 3) + 1):
        seen.extend(page_slice(items, page, 3))
    assert seen == items
","rationale":"With 10 items and 3 per page, total_pages should be 4 and page 4 should return the last item; on base it gives 3 and raises PageOutOfRange."}
